package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.memory.*; import com.wizzadrds.theworldremembers.relationship.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.fabricmc.fabric.api.entity.FakePlayer; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes; import net.minecraft.world.entity.npc.villager.Villager;
public final class VillagerCombatMemoryGameTest { @GameTest public void playerAttackIsRemembered(GameTestHelper c){Villager v=c.spawn(EntityTypes.VILLAGER,2,1,2);var p=FakePlayer.get(c.getLevel());p.setPos(3,1,2);c.runAtTickTime(1,()->{TheWorldRemembers.handleDamage(v,c.getLevel().damageSources().playerAttack(p),1f,1f,false);var memories=MemoryManager.get(c.getLevel().getServer()).memoriesOf(v.getUUID());if(memories.stream().noneMatch(m->m.type()==MemoryEventType.PLAYER_ATTACKED_NPC&&m.playerId().equals(p.getUUID()))){c.fail("Villager did not remember the player attack");return;}var rel=RelationshipManager.get(c.getLevel().getServer()).get(v.getUUID(),p.getUUID());if(rel==null||rel.fear()<=0||rel.resentment()<=0){c.fail("Attack did not change relationship");return;}c.succeed();});}}
